#!/usr/bin/env bash
# IKS Website — รุ่นรถชุดใหม่ 13 รุ่น / 45 รุ่นย่อย พร้อมราคาและรูป (ต้องติดตั้งเว็บ v9 ก่อน) · รันซ้ำได้
if [ "${BASH_SOURCE[0]:-$0}" != "$0" ]; then echo "กรุณารันด้วย: bash ${BASH_SOURCE[0]}"; return 1 2>/dev/null || exit 1; fi
set -euo pipefail
SELF="$(readlink -f "$0")"
MEDIA_DIR=${MEDIA_DIR:-/var/www/ikssa-media}
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
sed -n '/^__ARCHIVE_BELOW__$/,$p' "$SELF" | tail -n +2 | base64 -d | tar -xz -C "$TMP"
cat > "$TMP/models_v2.mjs" <<'NODE_EOF'
