  <defs>
    <linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f6f8fb"/><stop offset="0.62" stop-color="#e9edf3"/><stop offset="1" stop-color="#d5dce6"/></linearGradient>
    <radialGradient id="s" cx="0.5" cy="0.5" r="0.5"><stop offset="0" stop-color="#0c2346" stop-opacity="0.32"/><stop offset="1" stop-color="#0c2346" stop-opacity="0"/></radialGradient>
  </defs>
  <rect width="1200" height="750" fill="url(#g)"/>
  <rect y="560" width="1200" height="3" fill="#c27c45" opacity="0.35"/>
  <ellipse cx="600" cy="640" rx="470" ry="34" fill="url(#s)"/>
</svg>`);

async function cdn(rel) {
  const res = await fetch(`${CDN}/${rel}`, { signal: AbortSignal.timeout(30000) });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return Buffer.from(await res.arrayBuffer());
}

const media = [];
const q = (s) => (s === null || s === undefined ? 'null' : `'${String(s).replace(/'/g, "''")}'`);
async function addMedia(file, alt) {
  const meta = await sharp(path.join(MEDIA, file)).metadata();
  media.push(`(${q(file)}, ${q(path.basename(file))}, 'image/webp', ${statSync(path.join(MEDIA, file)).size}, ${meta.width}, ${meta.height}, ${q(alt)})`);
}

const imgs = {};
for (const [key, s] of Object.entries(SERIES)) {
  try {
    const raw = s.local ? readFileSync(path.join(LOCAL, s.local)) : await cdn(s.car);
    const trimmed = await sharp(raw).ensureAlpha().trim({ threshold: 1 }).png().toBuffer();
    const cut = await sharp(trimmed).resize(1140, 740, { fit: 'inside', withoutEnlargement: !!s.local }).toBuffer();
    const cm = await sharp(cut).metadata();
    const cutoutFile = `${DIR}/series-${key}-cutout.webp`;
    await sharp({ create: { width: 1200, height: 800, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } } })
      .composite([{ input: cut, left: Math.round((1200 - cm.width) / 2), top: Math.max(0, Math.round(800 - cm.height - 30)) }])
      .webp({ quality: 88, alphaQuality: 90 }).toFile(path.join(MEDIA, cutoutFile));
    const car = await sharp(trimmed).resize(1000, 520, { fit: 'inside' }).toBuffer();
    const km = await sharp(car).metadata();
    const cardFile = `${DIR}/series-${key}-card.webp`;
    await sharp(BG).composite([{ input: car, left: Math.round((1200 - km.width) / 2), top: Math.round(650 - km.height) }])
      .webp({ quality: 86 }).toFile(path.join(MEDIA, cardFile));
    const gallery = [];
    if (s.og) {
      try {
        const f = `${DIR}/series-${key}-gallery-1.webp`;
        await sharp(await cdn(s.og)).resize(1600, 1067, { fit: 'inside', withoutEnlargement: true }).webp({ quality: 84 }).toFile(path.join(MEDIA, f));
        gallery.push(f);
      } catch (e) { console.warn(`! ${key}: แกลเลอรีโหลดไม่ได้ (${e.message})`); }
    }
    for (const f of [cutoutFile, cardFile, ...gallery]) await addMedia(f, `ISUZU ${key}`);
    imgs[key] = { card: cardFile, cutout: cutoutFile, gallery };
    console.log(`✔ รูป ${key}`);
  } catch (e) {
    console.error(`✖ รูป ${key}: ${e.message} (ใช้รูปเดิม/อัปโหลดเองภายหลัง)`);
  }
}

// ---------- SQL ----------
const fmt = (n) => n.toLocaleString('en-US');
const uniq = (a) => [...new Set(a.filter((x) => x && x !== '-'))];
const out = ['set client_min_messages = warning;', 'begin;'];
if (media.length) {
  out.push(`insert into public.media_files (path, original_name, mime_type, size_bytes, width, height, alt_text) values\n  ${media.join(',\n  ')}\non conflict (path) do update set size_bytes = excluded.size_bytes, width = excluded.width, height = excluded.height;`);
}

VEHICLES.forEach((v, i) => {
  const prices = v.grades.map((x) => x.price).filter((p) => p !== null);
  const from = prices.length ? Math.min(...prices) : null;
  const to = prices.length ? Math.max(...prices) : null;
  const engines = uniq(v.grades.map((x) => `${x.engine} ${x.power} ${x.torque}`));
  const trans = uniq(v.grades.map((x) => x.transmission));
  const drives = uniq(v.grades.map((x) => x.drive));
  const specs = {
    'เครื่องยนต์': engines.join(' / '),
    'ระบบส่งกำลัง': trans.join(' / '),
    'ระบบขับเคลื่อน': drives.map((d) => (d === '4x2' ? '2 ล้อ (4x2)' : d === '4WD' ? '4 ล้อ (4WD)' : '4 ล้อ (4x4)')).join(' / '),
    'จำนวนรุ่นย่อย': `${v.grades.length} รุ่น`,
    ...(from ? { 'ช่วงราคาแนะนำ': from === to ? `${fmt(from)} บาท` : `${fmt(from)} – ${fmt(to)} บาท` } : {}),
  };
  const desc = `${v.name} ${v.tagline}\n\n${v.use}\n\n`
    + (from ? `ราคาแนะนำ${from === to ? '' : 'เริ่มต้น'} ${fmt(from)} บาท${from !== to ? ` ถึง ${fmt(to)} บาท` : ''} (${v.grades.length} รุ่นย่อย) `
            : 'กรุณาสอบถามราคาที่ปรึกษาการขาย ')
    + `เครื่องยนต์ ${engines.map((e) => e.split(' @')[0]).join(' และ ')} มีให้เลือก${trans.join('และ')}\n\n`
    + 'จองทดลองขับหรือขอใบเสนอราคาได้ที่อีซูซุกรุงเทพเซลส์ สาขาบางนา ศรีนครินทร์ บางเสาธง และเกษตร';
  const im = imgs[v.img];
  out.push(`insert into public.vehicles (slug, category_id, series, name, tagline, description, price_from, price_note, badge, specs, is_featured, status, sort_order${im ? ', image_card, image_cutout, gallery' : ''})
values (${q(v.slug)}, (select id from public.vehicle_categories where slug = ${q(v.cat)}), ${q(v.series)}, ${q(v.name)}, ${q(v.tagline)}, ${q(desc)}, ${from ?? 'null'},
  'ราคาแนะนำจากตรีเพชรอีซูซุเซลส์ อาจเปลี่ยนแปลงได้ · โปรโมชั่นสอบถามสาขา', ${q(v.badge ?? null)}, ${q(JSON.stringify(specs))}::jsonb, ${v.featured}, 'published', ${(i + 1) * 10}${im ? `, ${q(im.card)}, ${q(im.cutout)}, ${q(JSON.stringify(im.gallery))}::jsonb` : ''})
on conflict (slug) do update set category_id = excluded.category_id, series = excluded.series, name = excluded.name, tagline = excluded.tagline,
  description = excluded.description, price_from = excluded.price_from, price_note = excluded.price_note, badge = excluded.badge, specs = excluded.specs,
  is_featured = excluded.is_featured, status = 'published', is_visible = true, sort_order = excluded.sort_order${im ? ', image_card = excluded.image_card, image_cutout = excluded.image_cutout, gallery = excluded.gallery' : ''};`);
  out.push(`delete from public.vehicle_grades where vehicle_id = (select id from public.vehicles where slug = ${q(v.slug)});`);
  out.push(`insert into public.vehicle_grades (vehicle_id, name, price, engine, power, torque, transmission, drive, wheels, screen, features, sort_order) values\n  `
    + v.grades.map((x, k) => `((select id from public.vehicles where slug = ${q(v.slug)}), ${q(x.name)}, ${x.price ?? 'null'}, ${q(x.engine)}, ${q(x.power)}, ${q(x.torque)}, ${q(x.transmission)}, ${q(x.drive)}, ${q(x.wheels)}, ${q(x.screen === '-' ? null : x.screen)}, ${q(x.features)}, ${(k + 1) * 10})`).join(',\n  ') + ';');
});

const keep = VEHICLES.map((v) => q(v.slug)).join(', ');
out.push(`delete from public.vehicles where slug not in (${keep});`);
out.push(`delete from public.vehicle_categories c where c.slug in ('pickup', 'suv') and not exists (select 1 from public.vehicles v where v.category_id = c.id);`);
out.push('commit;');
out.push('\\pset footer off');
out.push(`select c.name as "กลุ่ม", v.name as "รุ่น", to_char(v.price_from, 'FM9,999,999') as "ราคาเริ่มต้น", (select count(*) from public.vehicle_grades g where g.vehicle_id = v.id) as "รุ่นย่อย"
  from public.vehicles v left join public.vehicle_categories c on c.id = v.category_id order by c.sort_order, v.sort_order;`);
writeFileSync(SQL_OUT, out.join('\n'));
console.log(`✔ เตรียมข้อมูล ${VEHICLES.length} รุ่น ${VEHICLES.reduce((n, v) => n + v.grades.length, 0)} รุ่นย่อย`);
if (!existsSync(SQL_OUT)) process.exit(1);
NODE_EOF
echo "▶ เตรียมรูปและข้อมูลรุ่นรถ…"
node "$TMP/models_v2.mjs" "$MEDIA_DIR" "$TMP" "$TMP/models.sql"
chmod 755 "$MEDIA_DIR/vehicles"; chmod 644 "$MEDIA_DIR"/vehicles/*.webp
docker exec -i iks-web-db psql -q -U iks_owner -d iks_web -v ON_ERROR_STOP=1 < "$TMP/models.sql"
echo; echo "✔ เสร็จแล้ว — ดูได้ที่ https://ikssa.io/models"
exit 0
